-- ---------- sys_role（1 行）----------
-- sys_role  系统角色表
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE IF NOT EXISTS `sys_role` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `role_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色名称',
  `role_key` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色编码（唯一）',
  `role_sort` int DEFAULT '0' COMMENT '角色排序',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0启用 1禁用',
  `data_scope` tinyint(1) NOT NULL DEFAULT '1' COMMENT '数据权限：1全部 2本部门 3自定义',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_key` (`role_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='系统角色表';

