  `form_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '表单控件：input/number/date/select/radio/textarea/image/file',
  `is_list` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否列表展示：1是 0否',
  `is_query` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否查询条件：1是 0否',
  `query_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '查询方式：eq/like/gt/lt/between',
