-- ---------- wf_category（1 行）----------
-- wf_category  流程分类表
DROP TABLE IF EXISTS `wf_category`;
CREATE TABLE IF NOT EXISTS `wf_category` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `code` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类编码（唯一）',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序号，越小越靠前',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0停用 1启用',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_wf_category_code` (`code`),
  KEY `idx_wf_category_sort` (`sort`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程分类表';

