-- ---------- wf_form（2 行）----------
-- wf_form  流程表单表
DROP TABLE IF EXISTS `wf_form`;
CREATE TABLE IF NOT EXISTS `wf_form` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `form_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '表单名称',
  `form_key` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '表单唯一标识',
  `form_json` longtext COLLATE utf8mb4_general_ci COMMENT '表单配置JSON（字段、组件、校验规则）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_wf_form_key` (`form_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程表单表';

