-- ---------- wf_model（2 行）----------
-- wf_model  流程模型表
DROP TABLE IF EXISTS `wf_model`;
CREATE TABLE IF NOT EXISTS `wf_model` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `model_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型名称（请假流程、报销流程）',
  `model_key` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型唯一Key（引擎识别）',
  `category_id` bigint DEFAULT NULL COMMENT '所属分类 wf_category.id',
  `form_id` bigint DEFAULT NULL COMMENT '绑定表单 wf_form.id',
  `bpmn_xml` longtext COLLATE utf8mb4_general_ci COMMENT 'bpmn-js导出的BPMN2.0 XML',
  `node_config` longtext COLLATE utf8mb4_general_ci COMMENT '节点审批人配置JSON（设计器维护）',
  `version` int NOT NULL DEFAULT '0' COMMENT '版本号，每次发布+1',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1已发布 2停用',
  `process_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '流程状态：0运行中 1完成 2驳回 3终止',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
