-- ---------- wf_listener（1 行）----------
-- wf_listener  流程监听器表
DROP TABLE IF EXISTS `wf_listener`;
CREATE TABLE IF NOT EXISTS `wf_listener` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `model_id` bigint NOT NULL COMMENT '关联流程模型 wf_model.id',
  `event_type` varchar(30) COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件类型：start启动 enter进入 complete完成 end结束 reject驳回',
  `action_type` varchar(30) COLLATE utf8mb4_general_ci NOT NULL COMMENT '动作：callback回调 notify通知 update_data改数据 log写日志',
  `callback_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '回调接口地址',
  `callback_param` text COLLATE utf8mb4_general_ci COMMENT '回调参数JSON',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  KEY `idx_wf_listener_model` (`model_id`,`event_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程监听器表';

INSERT INTO `wf_listener` (`id`,`model_id`,`event_type`,`action_type`,`callback_url`,`callback_param`,`status`,`create_by`,`create_time`,`update_by`,`update_time`,`is_deleted`) VALUES
