-- ---------- wf_instance（6 行）----------
-- wf_instance  流程实例表
DROP TABLE IF EXISTS `wf_instance`;
CREATE TABLE IF NOT EXISTS `wf_instance` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `instance_key` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '实例唯一标识（引擎token）',
  `model_id` bigint NOT NULL COMMENT '关联流程模型 wf_model.id（锁定版本）',
  `model_version` int NOT NULL DEFAULT '1' COMMENT '模型版本快照',
  `biz_key` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务单据号（如请假单号）',
  `form_data` longtext COLLATE utf8mb4_general_ci COMMENT '表单数据JSON',
  `start_user_id` bigint NOT NULL COMMENT '发起用户ID',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0运行中 1已完成 2已驳回 3已终止',
  `current_node` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '当前节点ID（并行时逗号分隔）',
  `start_time` datetime DEFAULT NULL COMMENT '发起时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `engine_state` longtext COLLATE utf8mb4_general_ci COMMENT '引擎运行状态JSON（网关到达记录、串行队列）',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_wf_instance_key` (`instance_key`),
  KEY `idx_wf_instance_model` (`model_id`),
  KEY `idx_wf_instance_start_user` (`start_user_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程实例表';

