-- wf_audit  审批记录表
DROP TABLE IF EXISTS `wf_audit`;
CREATE TABLE IF NOT EXISTS `wf_audit` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `instance_id` bigint NOT NULL COMMENT '关联流程实例 wf_instance.id',
  `task_id` bigint DEFAULT NULL COMMENT '关联流程任务 wf_task.id',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人用户ID',
  `action` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作类型：submit提交 approve同意 reject驳回 transfer转审 addsign加签 back退回',
  `comment` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审批意见',
  `node_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作所在节点ID',
  `node_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '节点名称',
  `create_time` datetime DEFAULT NULL COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_wf_audit_instance` (`instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='审批记录表';

