-- wf_file_config  附件上传/预览配置表
DROP TABLE IF EXISTS `wf_file_config`;
CREATE TABLE IF NOT EXISTS `wf_file_config` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `config_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置键',
  `config_value` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '配置值',
  `config_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '配置名称',
  `config_type` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '配置分组：upload上传 preview预览 storage存储',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='附件上传/预览配置表';

