-- ---------- wf_file（5 行）----------
-- wf_file  附件主表
DROP TABLE IF EXISTS `wf_file`;
CREATE TABLE IF NOT EXISTS `wf_file` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `file_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '存储文件名',
  `original_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '原始文件名',
  `file_ext` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文件后缀',
  `mime_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'MIME类型',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小（字节）',
  `file_md5` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文件MD5（去重用）',
  `storage_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'local' COMMENT '存储方式：local本地 minio对象存储',
  `storage_path` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '存储路径/对象key',
  `bucket` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '存储桶（MinIO）',
  `biz_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联业务类型（如审批单、报表、公告）',
  `biz_id` bigint DEFAULT NULL COMMENT '关联业务ID',
  `is_private` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否私有：0公共 1私有',
  `is_locked` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否归档锁定：0否 1是（锁定禁止删除）',
  `is_watermark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否预览水印：0否 1是',
  `expire_time` datetime DEFAULT NULL COMMENT '有效期（临时附件过期清理）',
  `upload_user_id` bigint DEFAULT NULL COMMENT '上传用户id',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  KEY `idx_md5` (`file_md5`),
  KEY `idx_biz` (`biz_type`,`biz_id`),
  KEY `idx_upload_user` (`upload_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='附件主表';

