-- ---------- msg_template（4 行）----------
-- msg_template  消息模板表
DROP TABLE IF EXISTS `msg_template`;
CREATE TABLE IF NOT EXISTS `msg_template` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `template_code` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板编码',
  `template_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板名称',
  `msg_type` varchar(30) COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息类型：todo待办 done已办 cc抄送 system系统 report报表 alarm告警 notice公告',
  `template_content` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '模板内容（含变量占位符）',
  `channel` varchar(30) COLLATE utf8mb4_general_ci DEFAULT 'site' COMMENT '推送渠道：site站内 sms短信 email邮件',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0停用 1启用',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='消息模板表';

