-- ============================================================================
-- 分组：定时任务 / 报表 / BI
-- ============================================================================

-- ---------- task_info（5 行）----------
-- task_info  定时任务信息表
DROP TABLE IF EXISTS `task_info`;
CREATE TABLE IF NOT EXISTS `task_info` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `task_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称',
  `task_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务唯一标识（Celery任务名）',
  `task_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '调度类型：cron间隔 interval间隔',
  `cron_expr` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'cron表达式',
  `interval_sec` int DEFAULT NULL COMMENT '间隔秒数',
  `params` text COLLATE utf8mb4_general_ci COMMENT '任务参数JSON',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0停用 1启用',
  `retry_on_fail` tinyint(1) NOT NULL DEFAULT '0' COMMENT '失败是否重试：0否 1是',
  `retry_count` int DEFAULT '0' COMMENT '重试次数',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人账号',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_key` (`task_key`)
