-- ---------- outer_api_config（3 行）----------
-- outer_api_config  外部接口配置表
DROP TABLE IF EXISTS `outer_api_config`;
CREATE TABLE IF NOT EXISTS `outer_api_config` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `api_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '接口名称',
  `api_url` varchar(500) COLLATE utf8mb4_general_ci NOT NULL COMMENT '接口地址',
  `method` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GET' COMMENT '请求方式：GET/POST/PUT/DELETE',
  `headers_json` text COLLATE utf8mb4_general_ci COMMENT '请求头JSON',
  `params_json` text COLLATE utf8mb4_general_ci COMMENT '请求参数JSON',
