-- ---------- outer_sync_task（3 行）----------
-- outer_sync_task  数据同步任务表
DROP TABLE IF EXISTS `outer_sync_task`;
CREATE TABLE IF NOT EXISTS `outer_sync_task` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `sync_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '同步任务名称',
  `api_id` bigint DEFAULT NULL COMMENT '来源接口ID outer_api_config.id',
  `target_table` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '目标本地表名',
