-- ---------- outer_api_request_log（4 行）----------
-- outer_api_request_log  外部接口请求日志表
DROP TABLE IF EXISTS `outer_api_request_log`;
CREATE TABLE IF NOT EXISTS `outer_api_request_log` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `api_id` bigint DEFAULT NULL COMMENT '接口ID outer_api_config.id',
  `api_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '接口名称快照',
  `request_url` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求地址',
  `request_param` text COLLATE utf8mb4_general_ci COMMENT '请求参数',
  `response_body` text COLLATE utf8mb4_general_ci COMMENT '返回结果',
  `http_code` int DEFAULT NULL COMMENT 'HTTP状态码',
  `cost_time` bigint DEFAULT '0' COMMENT '耗时（毫秒）',
  `error_msg` text COLLATE utf8mb4_general_ci COMMENT '异常信息',
  `request_time` datetime DEFAULT NULL COMMENT '请求时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_api_id` (`api_id`),
  KEY `idx_request_time` (`request_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='外部接口请求日志表';

