-- ---------- scene3d_data_bind（2 行）----------
-- scene3d_data_bind  模型数据绑定配置表
DROP TABLE IF EXISTS `scene3d_data_bind`;
CREATE TABLE IF NOT EXISTS `scene3d_data_bind` (
  `id` bigint NOT NULL COMMENT '雪花主键ID',
  `scene_id` bigint NOT NULL COMMENT '场景ID scene3d_scene.id',
  `object_id` bigint NOT NULL COMMENT '场景对象ID scene3d_scene_object.id',
  `bind_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '绑定名称',
  `data_source_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据源类型：db数据库 / api接口 / ws websocket',
  `source_config` json NOT NULL COMMENT '数据源配置、字段映射配置',
  `refresh_interval` int DEFAULT '30' COMMENT '轮询刷新间隔，单位秒，ws为0',
  `mapping_rule` json NOT NULL COMMENT '数值映射规则：区间、颜色、状态、动画',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0停用',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除 0否 1是',
  PRIMARY KEY (`id`),
  KEY `idx_scene_id` (`scene_id`),
  KEY `idx_object_id` (`object_id`),
  KEY `idx_status` (`status`),
