-- ---------- scene3d_alarm_rule（2 行）----------
-- scene3d_alarm_rule  3D可视化告警规则表
DROP TABLE IF EXISTS `scene3d_alarm_rule`;
CREATE TABLE IF NOT EXISTS `scene3d_alarm_rule` (
  `id` bigint NOT NULL COMMENT '雪花主键ID',
  `bind_id` bigint NOT NULL COMMENT '绑定配置ID scene3d_data_bind.id',
  `rule_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称',
  `compare_operator` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '比较符 > >= < <= = between',
  `threshold_value` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '阈值',
  `alarm_level` tinyint NOT NULL COMMENT '告警级别 1提示 2警告 3严重',
  `alarm_effect` json NOT NULL COMMENT '前端效果：闪烁、光晕、颜色、图标',
  `is_auto_notice` tinyint DEFAULT '1' COMMENT '是否自动推送消息',
  `is_auto_workflow` tinyint DEFAULT '0' COMMENT '是否自动发起审批工单',
  `workflow_def_id` bigint DEFAULT NULL COMMENT '关联工作流定义ID（SpiffWorkflow）',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0停用',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '是否删除 0否 1是',
  PRIMARY KEY (`id`),
  KEY `idx_bind_id` (`bind_id`),
  KEY `idx_alarm_level` (`alarm_level`),
  KEY `idx_status` (`status`),
  KEY `idx_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='3D可视化告警规则表';

INSERT INTO `scene3d_alarm_rule` (`id`,`bind_id`,`rule_name`,`compare_operator`,`threshold_value`,`alarm_level`,`alarm_effect`,`is_auto_notice`,`is_auto_workflow`,`workflow_def_id`,`status`,`remark`,`create_by`,`create_time`,`update_by`,`update_time`,`is_deleted`) VALUES
