  `id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `favorite_menus` varchar(1000) DEFAULT NULL,
  `home_layout` varchar(500) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='首页个性化配置表';


-- ---------- api_debug_log（0 行）----------
-- api_debug_log  接口调试日志表
DROP TABLE IF EXISTS `api_debug_log`;
CREATE TABLE IF NOT EXISTS `api_debug_log` (
  `id` bigint NOT NULL,
  `api_path` varchar(255) DEFAULT NULL,
  `method` varchar(10) DEFAULT NULL,
  `request_body` text,
  `response_body` text,
  `http_code` int DEFAULT NULL,
  `debug_user_id` bigint DEFAULT NULL,
  `cost_time` bigint DEFAULT NULL,
  `debug_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='接口调试日志表';


-- ---------- biz_student（4 行）----------
-- biz_student  学生信息表
DROP TABLE IF EXISTS `biz_student`;
CREATE TABLE IF NOT EXISTS `biz_student` (
  `id` bigint unsigned NOT NULL COMMENT '主键ID',
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生姓名',
  `age` int DEFAULT NULL COMMENT '年龄',
  `gender` tinyint(1) DEFAULT '0' COMMENT '性别（字典sys_user_sex）',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱',
  `enroll_date` date DEFAULT NULL COMMENT '入学日期',
  `score` decimal(5,2) DEFAULT NULL COMMENT '总分',
  `address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '家庭住址',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='学生信息表';

